#!/bin/sh
# rig egress firewall, generated by `rig webtools setup` (rig {{VERSION}}).
# Drops forwarded traffic from {{SUBNET}} into private address space, so a fetched
# page can never reach the LAN, a tailnet or a metadata address, whatever DNS said
# when rig checked the name: tinyproxy resolves the host again, and the deny-list in
# ../tinyproxy/filter only matches strings. These rules match the address the
# connection actually goes to.
#
# `apply` writes the rules into Docker's DOCKER-USER chain and stays up; `check`
# (the healthcheck) fails unless every rule is there, so tinyproxy and searxng do
# not start without them. The rules go in at the top, in this order: traffic inside
# the subnet (searxng to valkey on a host with br_netfilter), then replies to
# established flows, then the drops.
set -eu

SUBNET="{{SUBNET}}"
RANGES="0.0.0.0/8 10.0.0.0/8 100.64.0.0/10 127.0.0.0/8 169.254.0.0/16 172.16.0.0/12 192.0.0.0/24 192.168.0.0/16 198.18.0.0/15 224.0.0.0/3"

IPT=""
for b in iptables-nft iptables-legacy; do
  if "$b" -w -n -L DOCKER-USER >/dev/null 2>&1; then
    IPT="$b"
    break
  fi
done
if [ -z "$IPT" ]; then
  echo "rig egress firewall: no DOCKER-USER chain in iptables-nft or iptables-legacy (is this Docker's iptables backend?)" >&2
  exit 1
fi

rules() {
  echo "-s $SUBNET -d $SUBNET -j RETURN"
  echo "-s $SUBNET -m conntrack --ctstate RELATED,ESTABLISHED -j RETURN"
  for r in $RANGES; do
    echo "-s $SUBNET -d $r -j DROP"
  done
}

present() {
  rules | while read -r rule; do
    # shellcheck disable=SC2086
    "$IPT" -w -C DOCKER-USER $rule 2>/dev/null || return 1
  done
}

case "${1:-apply}" in
check)
  present
  ;;
apply)
  if ! present; then
    rules | while read -r rule; do
      # shellcheck disable=SC2086
      while "$IPT" -w -D DOCKER-USER $rule 2>/dev/null; do :; done
    done
    n=1
    rules | while read -r rule; do
      # shellcheck disable=SC2086
      "$IPT" -w -I DOCKER-USER "$n" $rule
      n=$((n + 1))
    done
  fi
  echo "rig egress firewall: active for $SUBNET ($IPT)"
  trap 'exit 0' TERM INT
  while :; do
    sleep 3600 &
    wait $!
  done
  ;;
*)
  echo "usage: egress.sh apply|check" >&2
  exit 2
  ;;
esac
